// Old Meetup library URLs. The listing lives on the club event now.
import React, { useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { Button, EmptyState, Page } from '../../components/ui';
import { NotFound, useCanModerate } from '../../components/mod';
import { eventIdForMeetup } from '../../lib/api';
import { colors } from '../../lib/theme';

export default function MeetupEventRedirect() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const { ready, ok } = useCanModerate();
  const [missing, setMissing] = useState(false);
  useEffect(() => {
    if (!ok || !id) return;
    let live = true;
    eventIdForMeetup(decodeURIComponent(id)).then((cid) => {
      if (!live) return;
      if (cid) router.replace(`/events/${cid}`);
      else setMissing(true);
    }).catch(() => { if (live) setMissing(true); });
    return () => { live = false; };
  }, [ok, id]);
  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok) return <NotFound />;
  if (!missing) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  return (
    <Page>
      <EmptyState icon="calendar-outline" title="No club event for this Meetup listing"
        body="Sync Meetup from Club events. A listing without a club event is created then, and Meetup shows under Publish to."
        action={<Button small variant="neutral" title="Club events" onPress={() => router.replace('/events')} />} />
    </Page>
  );
}
